mapper.select:
select a.*
from HR_SALARY_STANDARD a
         left join HR_SALARY_PAY b on a.ID = b.STANDARD_ID and b.DELETE_FLAG = 'NOT_DELETE' and b.TYPE = #{type} and b.ITEM_TYPE = #{itemType}
where a.DELETE_FLAG = 'NOT_DELETE' and a.TYPE='月工资标准' and a.`YEAR_MONTH` = #{yearMonth} and a.BIRTH_DAY is not null and MONTH(a.BIRTH_DAY) = #{month}
  and b.ID is null
